    public Step() {
        super("Step", 0, Module.Category.MOVEMENT);
        this.addModes("Vanilla", "NCP");
        this.addDouble("Height", 1, 1, 10);
    }

    @Override
    public void onDisable() {
        mc.thePlayer.stepHeight = 0.6F;
    }

    @Handler
    public Consumer<UpdateEvent> eventConsumer = (event) -> {
        height = this.getDouble("Height").floatValue();

        if (isMode("Vanilla")) {
            mc.thePlayer.stepHeight = height;
        } else {
            mc.thePlayer.stepHeight = 0.6F;
        }
    };

    @Handler
    public Consumer<ClimbSlabEvent> eventConsumer0 = (event) -> {
        if (isMode("NCP")) {
            double posX = mc.thePlayer.posX;
            double posY = mc.thePlayer.posY;
            double posZ = mc.thePlayer.posZ;
            if (event.isPre() && !Nekoware.INSTANCE.getModuleManager().getModule("Speed").isToggled()) {
                event.setStepHeight(1.0F);
            } else {
                double height = mc.thePlayer.getEntityBoundingBox().minY - mc.thePlayer.posY;
                if (height > 0.6F && height <= 1.0F) {
                    float[] values = { 0.42F, 0.75F };
                    for (float value : values)
                        mc.thePlayer.sendQueue.addToSendQueue(new C03PacketPlayer.C04PacketPlayerPosition(posX, posY + value, posZ, false));
                    mc.timer.timerSpeed = 0.4F;
                }
                timerSlow = 2;
            }
        }
    };

    @Handler
    public Consumer<UpdateEvent> eventConsumer1 = (event) -> {
        if (isMode("NCP")) {
            if (timerSlow <= 0 && timerSlow >= -2) {
                mc.timer.timerSpeed = 1.0F;
            }
            timerSlow--;
        }
    };

}


// NOTE (AI): The NCP mode is a pure C04 ladder: when the client-side bounding box rose more than 0.6 blocks (the vanilla step limit), it sends C04 y+0.42 false then y+0.75 false, and drops timerSpeed to 0.4 for two ticks. The server accepts the 1.0-block step because the client reports the intermediate positions, and the timer slowdown hides the resulting speed spike from horizontal checks. Vanilla mode just raises the local stepHeight, which works on servers that do not simulate stepping server-side. This is the same offset pair (0.42/0.75) used by NCP-speed and bhop modules, which is why the module disables itself while the client's Speed module is toggled.

